function taskDaysUntil(task){const today=Date.parse(`${new Date().toISOString().slice(0,10)}T00:00:00.000Z`);return Math.round((Date.parse(`${task.due_date}T00:00:00.000Z`)-today)/86400000)}
function taskDueLabel(task){if(task.status==='completed')return'Completed';const days=taskDaysUntil(task);return days<0?`Overdue by ${Math.abs(days)} day${Math.abs(days)===1?'':'s'}`:days===0?'Due today':days<=3?`Due in ${days} day${days===1?'':'s'}`:`Due ${task.due_date}`}
function taskReminderPanel(items){const active=items.filter(task=>task.status!=='completed'),overdue=active.filter(task=>taskDaysUntil(task)<0),dueSoon=active.filter(task=>taskDaysUntil(task)>=0&&taskDaysUntil(task)<=3),pending=active.filter(task=>task.status==='pending'),alerts=active.filter(task=>taskDaysUntil(task)<=3).sort((a,b)=>a.due_date.localeCompare(b.due_date));return panel('Due-date reminders',`<div class="stats"><div class="stat"><small>Overdue</small><b>${overdue.length}</b></div><div class="stat"><small>Due within 3 days</small><b>${dueSoon.length}</b></div><div class="stat"><small>Pending</small><b>${pending.length}</b></div></div>${alerts.map(task=>`<div class="lesson"><span class="tag">${esc(taskDueLabel(task))}</span><strong> ${esc(task.title)}</strong> · ${esc(task.due_date)}${task.employee?` · ${esc(task.employee)}`:''}</div>`).join('')||'<p class="muted">No overdue or upcoming deadlines.</p>'}`)}
