async function tasks(){return me.role==='employee'?employeeTasks():taskManagement()}
async function leave(){const [d,emp]=await Promise.all([api('/api/manage/leave_requests'),api('/api/manage/employees')]);html(panel('Create leave request',`<form id="leaveForm"><label>Employee<select name="employee_id">${emp.items.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><label>From<input type="date" name="from_date" required></label><label>To<input type="date" name="to_date" required></label><label>Reason<textarea name="reason" required></textarea></label><button class="primary">Submit</button></form>`)+panel('Leave approvals',table(d.items,[['employee','Employee'],['from_date','From'],['to_date','To'],['reason','Reason']],r=>statusActions(r,'leave_requests',['pending','approved','rejected']))));handleForm('leaveForm','/api/manage/leave',()=>show('leave'));bindStatuses()}
async function submissions(){const d=await api('/api/manage/submissions');html(panel('Student assignments',table(d.items,[['student','Student'],['course','Course'],['assignment','Assignment'],['content','Submission'],['grade','Grade']],r=>`<form class="grade" data-id="${r.id}"><input type="number" name="grade" min="0" max="100" value="${r.grade??''}" required placeholder="0–100"><input name="feedback" value="${esc(r.feedback)}" placeholder="Feedback"><button class="action">Grade</button></form>`)));document.querySelectorAll('.grade').forEach(f=>f.onsubmit=async e=>{e.preventDefault();try{await api('/api/manage/grade','POST',{id:f.dataset.id,...formData(f)});toast('Grade saved')}catch(e){toast(e.message)}})}
async function lessonsAdmin(){
 const [d,folderData]=await Promise.all([api('/api/manage/courses'),api('/api/manage/course-drive-folders')]);
 const folders=new Map(folderData.items.map(item=>[Number(item.course_id),item]));
 html(panel('Create lesson and add class recording',`<p class="muted">Videos must already be in the registered course folder in the admin-owned Google Drive.</p><form id="lessonForm"><label>Course<select name="course_id" id="lessonCourse" required>${d.items.map(course=>`<option value="${course.id}">${esc(course.title)}</option>`).join('')}</select></label><label>Lesson title<input name="title" maxlength="180" required></label><label>Lesson content<textarea name="content" maxlength="12000" required></textarea></label><input type="hidden" name="drive_file_id"><button class="secondary" id="chooseLessonVideo" type="button">Choose Drive video</button><span id="selectedLessonVideo" class="muted">No video selected</span><label>Order<input name="sort_order" type="number" value="5" min="1"></label><button class="primary">Publish lesson</button></form>`));
 const form=$('#lessonForm'),courseSelect=$('#lessonCourse'),pickerButton=$('#chooseLessonVideo');
 const updatePickerButton=()=>{pickerButton.disabled=!folders.has(Number(courseSelect.value));form.elements.namedItem('drive_file_id').value='';$('#selectedLessonVideo').textContent=pickerButton.disabled?'Register a Drive folder for this course first':'No video selected'};
 courseSelect.onchange=updatePickerButton;
 updatePickerButton();
 pickerButton.onclick=async()=>{
  const folder=folders.get(Number(courseSelect.value));
  if(!folder)return;
  try{
   const item=await chooseDriveItem({folderId:folder.folder_id});
   if(!item)return;
   if(!String(item.mimeType||'').startsWith('video/'))throw Error('Choose a video file');
   form.elements.namedItem('drive_file_id').value=item.id;
   $('#selectedLessonVideo').textContent=item.name;
  }catch(error){toast(error.message)}
 };
 form.onsubmit=async event=>{
  event.preventDefault();
  try{await api('/api/manage/lesson','POST',formData(form));toast('Lesson saved successfully');lessonsAdmin()}
  catch(error){toast(error.message)}
 };
}
async function tickets(){const d=await api('/api/tickets');html(panel('Open support request',form('ticketForm',[['subject','Subject'],['message','How can we help?','textarea']]))+panel('Support history',table(d.items,[['subject','Subject'],['message','Message'],['status','Status'],['reply','Reply'],['created_at','Created']],me.role==='admin'?r=>statusActions(r,'tickets',['open','resolved']):null)));handleForm('ticketForm','/api/tickets',()=>show('tickets'));bindStatuses()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const data=formData(e.target);try{const d=await portalAuth.signIn(data.email,data.password);me=d.user;token=d.csrf;shell()}catch(error){toast(error.message)}};
$('#showPasswordReset').onclick=()=>{$('#loginForm').hidden=true;$('#showPasswordReset').hidden=true;$('#passwordResetForm').hidden=false};
$('#cancelPasswordReset').onclick=()=>{$('#passwordResetForm').hidden=true;$('#loginForm').hidden=false;$('#showPasswordReset').hidden=false};
$('#passwordResetForm').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/auth/reset/request','POST',formData(e.target));toast(result.message);e.target.reset();$('#passwordResetForm').hidden=true;$('#loginForm').hidden=false;$('#showPasswordReset').hidden=false}catch(error){toast(error.message)}};
$('#logout').onclick=async()=>{try{await api('/api/auth/logout','POST',{})}catch(error){toast(error.message)}try{await portalAuth.signOut()}catch(error){toast(error.message)}location.reload()};
$('#menu').onclick=()=>$('aside').classList.toggle('open');
(async()=>{try{const d=await api('/api/auth/me');if(d.user){me=d.user;token=d.csrf;shell()}}catch{}})();
